) AS (
  VALUES 
    (332::BIGINT, 'Si de verdad está interesado en aprender, no tiene mejor elección que Eddy. Desde cuando la dificultad de un curso y el poder llevar su capacidad al limite se ha convertido en una critica al profesor? Tengan en cuenta que a la Universidad se va a estudiar, si necesita profesores faciles mejor salgas'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Clases excelentes']::TEXT[], '2026-10-22T00:00:00+00:00'::TIMESTAMPTZ, '05c5905de70ff63944194014af92beb606f5b77f2dae3b98b7dfa91702588fb1'::TEXT, ARRAY[1029]::BIGINT[]),
    (332::BIGINT, 'Un profesor con vocacion y explica bien, me parece q el problema con el q se encuentra es que el nivel educativo con el q se llega a la U baja cada año, aumentando quejas de dificultad, mas esto es poblema de la educacion en CR y toparse este profe en Intro es el mejor remedio (aunq toque repetir)'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Da crédito extra', 'Exámenes retadores']::TEXT[], '2026-10-15T00:00:00+00:00'::TIMESTAMPTZ, '00defc0983ab039c17903dd7acc29bc5601f88f4ae243da2faf97fe856d884f9'::TEXT, ARRAY[1029, 1020, 1022, 1045]::BIGINT[]),
    (332::BIGINT, 'Le encanta dar clase, se le nota las ganas de enseñar'::TEXT, 2.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Inspirador', 'Da crédito extra']::TEXT[], '2026-09-16T00:00:00+00:00'::TIMESTAMPTZ, 'eddad7daba511c7a3cdb6b66f2e5e4db6c3a62ed1b9266c1492d73b7c98123f9'::TEXT, ARRAY[1029]::BIGINT[]),
    (332::BIGINT, 'El comentario de abajo es muu cierto, él asume que uno conoce todo de los cursos previos y uno tiene que repasar para entender todo. Si hay grabaciones, repasen y hagan los extra!'::TEXT, 2.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Pocos exámenes', 'Exámenes retadores']::TEXT[], '2026-07-24T00:00:00+00:00'::TIMESTAMPTZ, '81299b714f4d6c215043c78961688a8fcdb414828df3b1ac99275b29c12f5684'::TEXT, ARRAY[1035]::BIGINT[]),
    (332::BIGINT, 'No entiendo porque tirarle tanto hate al mae, explica bien y es buena gente'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2026-07-01T00:00:00+00:00'::TIMESTAMPTZ, '81cd71e50895b1aac56a377acfb735f180ad4fb9178acccfc6b76f94645a6389'::TEXT, ARRAY[1045]::BIGINT[]),
    (332::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Exámenes retadores']::TEXT[], '2026-06-17T00:00:00+00:00'::TIMESTAMPTZ, '52154df40e1fdc3379b595aabbad558089a46c549b3b0b7c8d6319d834d0dbde'::TEXT, ARRAY[1037]::BIGINT[]),
    (332::BIGINT, 'Nunca me habían quebrado tanto y me había gustado tanto un curso'::TEXT, 2.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('45','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muy cómico', 'Clases excelentes']::TEXT[], '2026-05-20T00:00:00+00:00'::TIMESTAMPTZ, '61cdc19e017665277d1d04baf50d3e8ecac091e4b7dcdaca1d38285609875924'::TEXT, ARRAY[1035]::BIGINT[]),
    (332::BIGINT, 'Gracias a él entendí lo que es un conjunto congruencial completo'::TEXT, 2.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Exámenes retadores', 'Tomaría su clase nuevamente']::TEXT[], '2026-04-13T00:00:00+00:00'::TIMESTAMPTZ, 'ff521e832ce24634d45fba7a22b03aee91b2ba4908c2d0b842302b6f30e07367'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (332::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Deja trabajos largos', 'Clases excelentes']::TEXT[], '2026-02-08T00:00:00+00:00'::TIMESTAMPTZ, 'c9bed454e3714bf64cabb8358f07c3648e4289d129a8c3d1446e61591dda120b'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (332::BIGINT, 'Si es nuevo y piensa matricularlo piénselo dos veces para cualquier curso, con este compa sólo pasa Jimmy Neutron y Megamente. PD: Freddy Ramírez, mi amigo fiel.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchos exámenes', 'Deja trabajos largos']::TEXT[], '2024-12-03T00:00:00+00:00'::TIMESTAMPTZ, 'e44028075f48a8515bf1608ed01f2707b90ceff4eda633bb21504d3a4dbf5895'::TEXT, ARRAY[1154]::BIGINT[]),
    (332::BIGINT, 'Si el futuro depende de personas como Eddy, entonces nuestro futuro está jodido. Pobrecitos los que admiran a este mae, de verdad.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('50','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2024-10-22T00:00:00+00:00'::TIMESTAMPTZ, 'bcdde7b9507c040c7937d8b8eb94486515f019caf314b37a156a9097f0a93e43'::TEXT, ARRAY[1035]::BIGINT[]),
    (332::BIGINT, 'Es un comediante legalmente, con esas clases tan chistosas que da. Ni franco escamilla se atrevio a dar esos chistes, cagado de risa salí. Por cierto, que buena freddy ramirez xd'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico']::TEXT[], '2024-10-22T00:00:00+00:00'::TIMESTAMPTZ, '9785870e1ebe7cbd8a6c7bf1ca312b48a12f260e69498aa56f9b2bea7e89e62e'::TEXT, ARRAY[1043]::BIGINT[]),
    (332::BIGINT, 'Este profesor deberia ser investigado por el TEC, cree que su forma de dar la clases es la unica correcta, fuera de él, los profesores son malos segun sus comentarios, le da igual el programa de estudio da la materia que quiere, y evalua en binario, absurdo..'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Requiere mucha lectura']::TEXT[], '2024-10-22T00:00:00+00:00'::TIMESTAMPTZ, '7db147d4b85781302929426af64effce7579066967f169053876d6804aae876b'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (332::BIGINT, 'No lo recomiendo, es el peor profesor con el que he estado en toda la carrera, humilla y trata mal a los estudiantes, además se cree superior a cualquier otro ser en la tierra que opine diferente a él, de lo mejores consejos que puedo dar es: no matricule con el, y si lo hace va a sufrir'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2024-10-04T00:00:00+00:00'::TIMESTAMPTZ, '791e8b34d18eb49302f80eb7637b556a0c0e055d23a742627c4a281b4348ad26'::TEXT, ARRAY[1154]::BIGINT[]),
    (332::BIGINT, 'Respondiendo al NPC abajo de esta calificación (Eddy?), cualquier estudiante de la sede no comparte esa opinión. Si quieren perder el tiempo matriculen a este profe. No tiene respeto por los estudiantes y ademas escribió un ensayo ofensivo sobre un estudiante que dijo que ya no estaba para aprender.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchos exámenes', 'Exámenes retadores']::TEXT[], '2024-09-02T00:00:00+00:00'::TIMESTAMPTZ, '971102162a33dcacec7b3714ccb042323e28f83cac11b3a82a1c08a2d0abe955'::TEXT, ARRAY[1045, 1154]::BIGINT[]),
    (332::BIGINT, 'Si algún miembro del TEC lee esto, sería importante que este profesor sea investigado lo más pronto posible, trata mal a los estudiantes, no enseña lo que debería y se cree un genio (realmente es y se ve muy tonto). No tiene vocación como profesor y está destruyendo la educación superior.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('30','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-07-26T00:00:00+00:00'::TIMESTAMPTZ, 'f6112df4620cea91a1325e7e8cd51b9140973c3758af3005382856f4313056b0'::TEXT, ARRAY[1054]::BIGINT[]),
    (332::BIGINT, 'Eddy se va a penales con Kirstein en ver quien es el peor profesor del TEC. Aunque que Kirstein por lo menos tiene el ego controlado, Eddy no, él se cree Linus Torvalds.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-06-23T00:00:00+00:00'::TIMESTAMPTZ, 'c4dc07cc1481e26bd8955a938ea2eb1485e4688181342a475f8e79a7d3d01a6d'::TEXT, ARRAY[1054]::BIGINT[]),
    (332::BIGINT, 'Nunca matricule :) Todos los trabajos del curso siempre me dejaban cansada. El proyecto lo calificó de manera súper injusta. Semana 7 todos estábamos reprobados menos 2. Semana 8 nos dimos de baja los 18 restantes. Califica bien a los que le agradan (incluso sale a comer con esos estudiantes).'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clase fácil', 'Muchas tareas']::TEXT[], '2024-06-19T00:00:00+00:00'::TIMESTAMPTZ, 'd0c831058472d01e5ee74c3383dee20d7d9a9f5aea0cd6cb3c6b517a5b0cf0e3'::TEXT, ARRAY[1054]::BIGINT[]),
    (332::BIGINT, 'El mae se cree el mejor del mundo y el mejor profe del TEC. Es buen programador pero pésimo profesor. Egocéntrico y la carga académica es exagerada. Da varas que ni siquiera son del curso que está dando y se burla de los estudiantes. De 30 pasan 5, 2 por nota y 3 por argolla. No matriculen con él.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Exámenes retadores']::TEXT[], '2023-12-04T00:00:00+00:00'::TIMESTAMPTZ, '61c16b54354004533a4fdac2414117b79b7224567b40184e147c01fe25af3ffc'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (332::BIGINT, 'Un profesor que piensa que el estudiante no tiene vida, no tiene otras materias, no hace nada más que llevar su curso. Tiene una obsesión por pavonearse y el pensamiento de "solo los más bravos pasan mi curso" como si soportar su infierno de clase fuera un mérito en sí mismo. Ojalá aprenda humildad'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil', 'Muchas tareas']::TEXT[], '2023-09-05T00:00:00+00:00'::TIMESTAMPTZ, '1a366e2778b811fb6af56530f8084731ff6937c01bfcceb43df852967e0fded0'::TEXT, ARRAY[1035]::BIGINT[]),
    (332::BIGINT, 'Eddy es como la mostaza, o lo ama o lo odia, yo personalmente odio la mostaza, pero p no implica q'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Inspirador', 'Deja trabajos largos']::TEXT[], '2023-08-19T00:00:00+00:00'::TIMESTAMPTZ, '6a2ca30d3f3fc14fd3301832444fbeafb806abcfdf7c7998a695b9a02b53228f'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (332::BIGINT, 'Apoyo lo que el comentario de abajo dice sobre que el mae quiere enseñar más de lo que debe (si quiere título fácil vaya a la Latina vagazo). Eddy pretende que uno viva coma y cag*e programación todo el día y pues no es justo uno tiene una vida y para eso está también la cantidad de créditos...'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-07-27T00:00:00+00:00'::TIMESTAMPTZ, 'ee31379f8b67d6f0c80ac9106baa495bd11d429cb58fc901c90d9990dc2c6e4a'::TEXT, ARRAY[1035]::BIGINT[]),
    (332::BIGINT, 'Aprende demasiado con el profe solamente que si debes ponerle demasiado de su parte y envés el profe llega a ser un poco de mal gusto al consultar si no entendes algo te va a decir que lo vieron la primera semana o este tipo de comentarios'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Asistencia obligatoria']::TEXT[], '2023-06-26T00:00:00+00:00'::TIMESTAMPTZ, '18f851f4ea1ae12fecb7ceca2a1cbac2ec8f15c07cc6d3150b32ef7b6d641d19'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (332::BIGINT, 'Estima mucho a sus estudiantes que es la razón por la que no baja la dificultad de sus cursos, los hace muy duros, pero explica muy bien y resuelve cualquier duda que se le haga. Da un tiempo adecuado para sus tareas, pero eso sí, en general requiere mucho de su tiempo para aprobarlo.'::TEXT, 2.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Exámenes retadores']::TEXT[], '2023-06-22T00:00:00+00:00'::TIMESTAMPTZ, 'a5cf9e20eb8a38c0d8700b83cbf9eebb7d3016e8907226f20daa2993f2a900a7'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (332::BIGINT, 'La peor experiencia para entrar a la universidad es llevar con don Eddy, este man diariamente tiene que recordarse lo inteligente que es, lo mucho que nos supera a todos y sobre todo torturarnos con que estamos en el TEC y aquí no se duerme'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-06-13T00:00:00+00:00'::TIMESTAMPTZ, 'cb58659200446bdb4a20c319337884a4756bdb579b1e84c1da04351899752321'::TEXT, ARRAY[1022, 1020]::BIGINT[]),
    (332::BIGINT, 'diay que digo, el mae nos ve a todos cómo chiquillos tontos recién salidos del cole, jurelo que para el mae somos mongolitos. Siempre raja de su inteligencia y dios libre llevarle la contraria, preparese para que el mae se burle de usted'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-05-20T00:00:00+00:00'::TIMESTAMPTZ, '6c31f4ffca56e158ee2fe90f8e5751deab79178cc22c14427e228b64d40d6d24'::TEXT, ARRAY[1020]::BIGINT[]),
    (332::BIGINT, 'Eddy es un caso, de esos profes que uno no le desea ni al peor enemigo, es altanero, grosero, egocéntrico y sobretodo explotador, él piensa que enseñar es reventar al estudiante con tareas y proyectos exagerados cómo si uno viviera sólo por y para el TEC'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-05-02T00:00:00+00:00'::TIMESTAMPTZ, '8d1e5acb2dd4d7f66c496441f9b348c253762a88390d6921d61ada9e2f8c9d6f'::TEXT, ARRAY[1154]::BIGINT[]),
    (332::BIGINT, 'Es el peor profe que he conocido, el enseña mate en todos los cursos no importa el curso, lo único que hace es rajar de su inteligencia y se cree el mejor profe del mundo, no vayan con él, todo lo malo que dicen de él es cierto, solo humilla a los estudiantes.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2023-03-28T00:00:00+00:00'::TIMESTAMPTZ, 'ccd20c025212e4ad0d6b0d7525b7280954ba1536f81cf55bec2f775b378954dd'::TEXT, ARRAY[1154]::BIGINT[]),
    (332::BIGINT, 'Su semestre se puede ir sólo en tratarle de quedar bien a este señor y sus abundantes tareas, mi recomendación es no se comprometa con los cursos de Eddy, salve todos los demás cursos y no vuelva a meter con él, no vale la pena el desgaste para quedarle bien'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-03-27T00:00:00+00:00'::TIMESTAMPTZ, '31c306f5c99273f8cb510873039f8a6513f6f3b8ae937ceffe4fca93f95ea58f'::TEXT, ARRAY[1035]::BIGINT[]),
    (332::BIGINT, 'El peor profesor del TEC mejor que deje de humillar gente en sus clases porque asi es imposible llevar cursos con el'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-02-17T00:00:00+00:00'::TIMESTAMPTZ, '2f82684346c2b945826351bcb6eda362902f58c68f535967427093e44dd93084'::TEXT, ARRAY[1035]::BIGINT[]),
    (332::BIGINT, 'La verdad es que no iba con miedo por lo que leí aqui, pero el curso fue super interesante, aprendí mucho, la evaluación fue justa (6 proyectos) y en general no lo sentí pesado.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Aspectos de calificación claros']::TEXT[], '2023-01-31T00:00:00+00:00'::TIMESTAMPTZ, '9516c600ff98c34a9581e1e2fcf45a7d9ff807bc0427b37229476a3c4be5676f'::TEXT, ARRAY[1132]::BIGINT[]),
    (332::BIGINT, 'El profe es bastante bueno y ayuda bastante con los proyectos. El curso no fue pesado y él explica bastante bien. A veces se sale de los temas de clase, pero eso puede resultar interesante. Si le molesta su humor se puede limitar a los temas de clase.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2023-01-26T00:00:00+00:00'::TIMESTAMPTZ, 'af1f172028377ab290bb7e444169962d8ab6b9389b2a16199098fa4fd1825898'::TEXT, ARRAY[1132]::BIGINT[]),
    (332::BIGINT, 'Malo con M de "Mejor hubiera metido otro curso y me ahorro el colerón de ir a las clases del mae más cae mal del tec"'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-12-09T00:00:00+00:00'::TIMESTAMPTZ, '95479f252c2fcfbb144a972e6ccb6753208f1b6c9716e06c1306c648edf67c2a'::TEXT, ARRAY[1045]::BIGINT[]),
    (332::BIGINT, 'Califica duro, deja tareas que hacen parecer que el curso vale 10 créditos, los proyectos son sumamente complicados y a todo eso súmele que el profesor tiene las soft skills en -20. Atrase la carrera, meta otros cursos o meta en otra sede pero nunca meta con este profe.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-11-21T00:00:00+00:00'::TIMESTAMPTZ, '2ae496be7653ba19a741d4acba1f84676a0f73f8a0d1b2d67bcd505c50b78d1c'::TEXT, ARRAY[1035]::BIGINT[]),
    (332::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Exámenes retadores']::TEXT[], '2022-11-17T00:00:00+00:00'::TIMESTAMPTZ, 'f47703220bc1581fdaa287dc471a2bc6fb1f838ec615ac3741f5f5d82749314c'::TEXT, ARRAY[1035]::BIGINT[]),
    (332::BIGINT, 'Si juega tanto de inteligente debería estar dando clases en Harvard o el MIT, tal vez allá la gente "sí esté a su nivel". Pedante creído'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-10-22T00:00:00+00:00'::TIMESTAMPTZ, 'd55b2a0de83259b5df76b32f9443c7c29e4addae9bfe3c3c984450cf5b16ad50'::TEXT, ARRAY[1045]::BIGINT[]),
    (332::BIGINT, 'Este mae se las da de super inteligente, no respeta a nadie y se cree que solo él tiene la razón en todos los temas, sea política, religión, universidad... El mae jura que todos a su alrededor somos un montón de perdedores que ni le llegan a los talones. Asco dan los creídos cómo este mae.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-10-11T00:00:00+00:00'::TIMESTAMPTZ, '33d0f859dd3ad4b755df0d216f6f9915099fedcf24b1794a5a16fa88a310cb85'::TEXT, ARRAY[1045]::BIGINT[]),
    (332::BIGINT, 'El profesor piensa que su curso es el único, no respeta temas de salud mental y tiene la idea de que "si no logran mis tareas es porque son unos idiotas"'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-10-09T00:00:00+00:00'::TIMESTAMPTZ, '268b9cd30d1c0ecc3c5d0027782a5cf3f2b5a049cd9128cc20a486a99e2464fd'::TEXT, ARRAY[1045]::BIGINT[]),
    (332::BIGINT, 'No lo soporto, 2 semestres seguidos llevando con Eddy todo porque la sede de Alajuela es un asco, en vez de poner a los profes buenos cómo Diego o Víquez a dar bastantes cursos no, los peores profes son los que más se repiten. Mi consejo: váyase a otra sede si quiere tener salud mental'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-08-23T00:00:00+00:00'::TIMESTAMPTZ, '1fa175cb68134ab2e3076a964b2eb1b4c5b9d7cede176d761bbf3f34f33d690e'::TEXT, ARRAY[1045]::BIGINT[]),
    (332::BIGINT, 'No hay suficiente espacio en la clase para el ego del profesor'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-08-17T00:00:00+00:00'::TIMESTAMPTZ, 'bc1298c9d3f6060a511b8e07f6f952122955c03b34829590922ef0db6bb776ec'::TEXT, ARRAY[1035]::BIGINT[]),
    (332::BIGINT, 'El semestre viene empezando y este mae no ha parado de joder. Todo lo que aquí dicen es bastante cierto'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-08-08T00:00:00+00:00'::TIMESTAMPTZ, 'be47abb518491ec8492cfff943df88d26e9dd1332aaa38bd885bcb95b9cfd5b9'::TEXT, ARRAY[1045]::BIGINT[]),
    (332::BIGINT, 'El TEC tiene malos profes pero santa virgen de la papaya ninguno cómo Eddy, este man te trauma al punto que vos pensás que mejor deja la carrera porque no quiere más presión.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-07-31T00:00:00+00:00'::TIMESTAMPTZ, 'd8cac71abdc5dbf22a40540eab7ad9a319957bbffcf9141585c5e4c9df37d94e'::TEXT, ARRAY[1035]::BIGINT[]),
    (332::BIGINT, 'La verdad es un buen profe, sabe mucho y le gusta enseñar, sin embargo no sabe tratar a los demás, al punto que los termina humillando, si tan solo trabajara un poco sus habilidades blandas, este profe llenaría aulas y no solo 5 espacios de personas que no tuvieron otra opción que llevar con él.'::TEXT, 2.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da crédito extra', 'Brinda apoyo']::TEXT[], '2022-07-21T00:00:00+00:00'::TIMESTAMPTZ, '92a7fc7990bb4284a070fe2892456d9ea272f9956c3e1dffe6b5519fc98a8bdb'::TEXT, ARRAY[1020]::BIGINT[]),
    (332::BIGINT, 'Por personas cómo este profe es que allá afuera muchos creen que los del TEC somos un montón de ingenierillos egocéntricos con 0 habilidades blandas y que solo saben jugar de intelectuales para hacerse lucir. Lamentablemente que un profesor sea así'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-07-19T00:00:00+00:00'::TIMESTAMPTZ, '9bc0e03e8b6f2febb6f6ca579a484899c4443dd041719535221393c74cd7549f'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (332::BIGINT, 'Cada vez que este mae abría la boca para dar su "humilde opinión" alguien salía humillado o sencillamente se echaba miel a sí mismo por ser mejor que todos los seres humanos del mundo. Jamás llevaría otro curso con él'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-07-14T00:00:00+00:00'::TIMESTAMPTZ, 'cd13251b890f9a4cfef4a316699522f6515ef852330d5c06f32deb9bf740e60e'::TEXT, ARRAY[1022, 1020]::BIGINT[]),
    (332::BIGINT, 'Con Eddy hay 2 opciones, o él tiene la razón o ud es un pendejo. El mae se cree la última coca del desierto, la reencarnación de Einstein, se piensa que es súper inteligente y que todos somos un montón de idiotas.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-07-09T00:00:00+00:00'::TIMESTAMPTZ, 'aa865bd313798a765f3c69519b25eb3a919b3c4c2aec62e408b536430d835125'::TEXT, ARRAY[1035]::BIGINT[]),
    (332::BIGINT, 'Es un profe bueno regular, le gusta enseñar y se nota, depende mucho del estudiante si le agrada o no. Es muy energético y exigente, califica duro y los trabajos son difíciles. A veces cuesta entenderle pero explica cosas que otros profes no, mucha gente se quedó con él, cada quien mide ahí.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Exámenes retadores']::TEXT[], '2022-06-27T00:00:00+00:00'::TIMESTAMPTZ, '0529b05d7d618cf404ff52af0f58036e06cdb12154630459770f0c39ac00ebfc'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (332::BIGINT, 'Innecesariamente matado, cómo dicen comentarios atrás, es un académico que no entiende que su curso no es el único en el mundo. Si puede meter con otro profesor hágalo'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-06-26T00:00:00+00:00'::TIMESTAMPTZ, 'c28e1832c4a254e414a0ddf928cb3534b680f95a84365ae54adb097609f7aae0'::TEXT, ARRAY[1035]::BIGINT[]),
    (332::BIGINT, 'Normalmente no escribo aquí, pero él es excelente profesor y excelente persona y no merece lo que se dice aquí.'::TEXT, 2.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2022-06-24T00:00:00+00:00'::TIMESTAMPTZ, 'bd6fa383fd2f1eb4363a0e0650719e210c9edf370348adce6e133acc5e38900f'::TEXT, ARRAY[1035]::BIGINT[]),
    (332::BIGINT, 'Va a mamar todo el semestre, pero uno aprende mucho más que con otros profes'::TEXT, 2.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Tomaría su clase nuevamente']::TEXT[], '2022-06-12T00:00:00+00:00'::TIMESTAMPTZ, '4e837e79d346a1ccb3d1aa61a46cd9874b57d4d0fc3059054f4ac0b280cf30c8'::TEXT, ARRAY[1035]::BIGINT[]),
    (332::BIGINT, 'De esos profes que piensan que su curso es el único y el más importante, a eso sumele que es un gran engreído que piensa que todos, desde profes hasta alumnos, somos un montón de idiotas y nadie le llega a los talones.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-06-04T00:00:00+00:00'::TIMESTAMPTZ, 'a14fcea84b667561e6f29288d53b73274154fe98a4478e1b88e62bb9d5804c46'::TEXT, ARRAY[1035]::BIGINT[]),
    (332::BIGINT, 'Llevar cualquier curso con el es una basura, desde la primer semana deja un montón de tareas durísimas, si aprecia su salud mental, no meta con él.'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2022-06-03T00:00:00+00:00'::TIMESTAMPTZ, '6071c0b4a695a0911615f21ecb36b9c2a63b68699f19568b0e2936e46d0524d5'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (332::BIGINT, 'No vale la pena matarse en un curso solo por quedarle bien a un profesor tan pedante y egocéntrico'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-05-19T00:00:00+00:00'::TIMESTAMPTZ, 'e26d11727b1b01fe7f75e2e028964e7f592f52f3520c9301aaf1386267eb91f0'::TEXT, ARRAY[1035]::BIGINT[]),
    (332::BIGINT, 'Quitaron al profe Diego y pusieron a este mae y boom! ahora medio mundo dice que algoritmos es duro. Una lástima, yo quería aprender, no quería sólo hacer un montón de tarea y proyectos hasta el cansancio.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2022-04-21T00:00:00+00:00'::TIMESTAMPTZ, '54dfb4647bc896f3847c89a03ae02690ce3d899155b4657cb3e189095d0faf4f'::TEXT, ARRAY[1035]::BIGINT[]),
    (332::BIGINT, '"Arriba los egocéntricos" y este mae pegó en un satélite. Jamás había conocido a alguien tan creído y juega de genio en mi vida haha'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas']::TEXT[], '2022-04-01T00:00:00+00:00'::TIMESTAMPTZ, 'a0d384a2d85a479b0966c4664a67cb4f8b452f9280a2e5fcd9747d72b5dc5427'::TEXT, ARRAY[1035]::BIGINT[]),
    (332::BIGINT, 'Solo 2 semanas con él para comprobar todo lo que aquí se dice, diosito ayúdame'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-02-21T00:00:00+00:00'::TIMESTAMPTZ, '25b53aac459a1dfc72a3d2e54fb013139daa9f62467050583fdf4bc977841b9c'::TEXT, ARRAY[1035]::BIGINT[]),
    (332::BIGINT, 'En todos los cursos existe el morro castroso que quiere jugar de intelectual, en este caso el morro castros es el profesor'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-02-04T00:00:00+00:00'::TIMESTAMPTZ, '078a36b95996c8f09c7ae8bef4a7c8917cf6df0c5a559b87def3be81c4f602e3'::TEXT, ARRAY[1154]::BIGINT[]),
    (332::BIGINT, 'Sí, este curso es difícil, pero eso no justifica la sarta de cosas que le dedican en este foro. Él es una gran persona, siempre está dispuesto a ayudar y reconoce la participación activa. Ahora, el curso es difícil, pero va aprender. No hay otro profe en la sede que domine tanto el tema como él.'::TEXT, 2.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('50','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'La participación importa']::TEXT[], '2022-01-30T00:00:00+00:00'::TIMESTAMPTZ, 'bd639c6b737dc16ec821c3afba7b1d629b8f71841bbaee92130793c065904a94'::TEXT, ARRAY[1035]::BIGINT[]),
    (332::BIGINT, 'Con este profe se aprende un montón y cómo no si el mae deja tareas, proyectos y exámenes que literal le van a consumir día y noche, sería el colmo si uno no aprende después de pasar 24/7 pegado a su materia, fue un infierno llevar con él.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2022-01-12T00:00:00+00:00'::TIMESTAMPTZ, 'ca5493fdd8e280b94df8c09cc4d4c63efdf045b5aba707900c953a8b21050246'::TEXT, ARRAY[1035]::BIGINT[]),
    (332::BIGINT, 'Hay destinos peores que la muerte. Matricular con este mae es uno de ellos'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2021-12-24T00:00:00+00:00'::TIMESTAMPTZ, '8fd25adc80934315f5256cdbcba80bfbd9e875bcfc64ab8597156c857109e2ce'::TEXT, ARRAY[1035]::BIGINT[]),
    (332::BIGINT, 'Muy exagerado, el profe exige cómo si el curso valiera 12 créditos, los exámenes difíciles, los proyectos ufff ni hablar. Las clases no son tan tuanis porque el mae se las da de muy genio y depende puede hasta humillar al alumno pero bueno. Lo mejor es meter con otro.'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-12-04T00:00:00+00:00'::TIMESTAMPTZ, 'f84dadb6fda490164ad76b0e73230bdbfd8581fd67d6274c8428c014b5e09aaa'::TEXT, ARRAY[1154]::BIGINT[]),
    (332::BIGINT, 'El curso abarca los temas de sistemas operativos de una manera adecuada, las clases son interesantes. Los exámenes son difíciles. Los proyectos extensos pero con organización y un equipo responsable se obtienen buenas notas en los proyectos. El profesor brinda ayuda en cualquier momento'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2021-12-02T00:00:00+00:00'::TIMESTAMPTZ, '95f7dfe320cad23cffd3352b7d4c3bd8ed1f838ec4166403b01f36c4025637c0'::TEXT, ARRAY[1154]::BIGINT[]),
    (332::BIGINT, 'Si se quiere tener una buena calidad a la hora de estudiar es un profe muy recomendable. Tener en cuenta que son cursos un poco pesados pero valen mucho la pena. Por último, mencionar que es un profesor que brinda mucha ayuda a sus estudiantes.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-11-22T00:00:00+00:00'::TIMESTAMPTZ, '663e81553212e4bbf14a203170ae5781c0947834c5a861618556532cc8ba9d19'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (332::BIGINT, 'Este señor piensa que su curso vale 16 créditos y que es el único que llevamos. Además, su ego ufffff yo nunca había conocido a alguien tan creído en mi vida, él piensa que todos somos un poco de idiotas'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-11-16T00:00:00+00:00'::TIMESTAMPTZ, '71fd9a425377594fc03a2d93e2ab3132a270583ff58f46ee253859f2ba8daf20'::TEXT, ARRAY[1029]::BIGINT[]),
    (332::BIGINT, 'Preparese para vivir y respirar tarea desde que empieza el semestre hasta que termina.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-11-10T00:00:00+00:00'::TIMESTAMPTZ, '132ea1545ca078612cf75b126b983de9ae862b641da6c90a1373425ddc7c07e7'::TEXT, ARRAY[1035]::BIGINT[]),
    (332::BIGINT, 'El profe es un atentado contra la salud mental de cualquier estudiante por lo que ya otros comentarios aquí dicen, evítelo a toda costa.'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas']::TEXT[], '2021-10-09T00:00:00+00:00'::TIMESTAMPTZ, '8915a543962d8237a7e8315b746a19aacab1026811827581c74c9a8898c99260'::TEXT, ARRAY[1029]::BIGINT[]),
    (332::BIGINT, 'Cómo profesor se ve que sabe mucho pero le falta la parte pedagógica, los trabajos que pide son horriblemente complicados.'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-09-29T00:00:00+00:00'::TIMESTAMPTZ, 'f88a0edfd8a35728df0b019d09f927c04bd40acd2fd1946b255d7e10d1e779dc'::TEXT, ARRAY[1035]::BIGINT[]),
    (332::BIGINT, 'Que infierno llevar clases con este mae, todo lo complica más de lo normal, les recomiendo mejorar su nota de matricula para que puedan meter en otra sede y eviten a este "genio".'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-09-09T00:00:00+00:00'::TIMESTAMPTZ, '79d57a68fa65296f9058efeb74170c360ec6382cf26202fb8264860535d1bd84'::TEXT, ARRAY[1029]::BIGINT[]),
    (332::BIGINT, 'Demasiado creído, egocéntrico y absorbente. Desde el día 1 usted no va tener un respiro de este señor. "Salud mental? Eso es para débiles" me imagino que ese debe ser su lema'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil']::TEXT[], '2021-08-27T00:00:00+00:00'::TIMESTAMPTZ, '710c03ce072acd4f0cd36fa8a9463af9c4b517d876f7d8cdf72ab706c2d36351'::TEXT, ARRAY[1035]::BIGINT[]),
    (332::BIGINT, 'De verdad recomiendo no llevar nada con el, menos si usted está entrando a la U por primera vez'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('55','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Exámenes retadores']::TEXT[], '2021-08-24T00:00:00+00:00'::TIMESTAMPTZ, 'ba39a843a5bad2784292d3a1d47f9cd18aa60293f97f4d86ec4be5fad3d9342d'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (332::BIGINT, 'Es muy académico, de esos profes que no saben cómo funciona el mundo real y enseñan desde una perspectiva 100% teórica-académica, lo cual hace que todo sea muy pesado.'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-08-10T00:00:00+00:00'::TIMESTAMPTZ, '1b28364a7d86420f8fe45bbe4c98a89fb7e707d5239781a4a180800bf48631c2'::TEXT, ARRAY[1035]::BIGINT[]),
    (332::BIGINT, 'Prefiero cortarme un pie a volver a llevar con este mae'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clase fácil', 'Muchas tareas']::TEXT[], '2021-07-15T00:00:00+00:00'::TIMESTAMPTZ, '58dceb6d3ce26f82e6b21a1f82de7da1ffae489487f5764bccdd55c077ffe6ff'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (332::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Exámenes retadores']::TEXT[], '2021-07-06T00:00:00+00:00'::TIMESTAMPTZ, 'a53aa8dd312f0ae6c19cabe84c7c3e5b3e868cb777bcf501d7713b6da387a36a'::TEXT, ARRAY[1020]::BIGINT[]),
    (332::BIGINT, 'Ahora que en el grupo de facebook del tec se habla sobre los profes pésimos que sobrecargan al estudiante me acordé de comentar que le huyan a este profesor. Tal vez aprenda mucho (cómo no, si los trabajos son pesadisimos) pero su salud mental es más importante'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Deja trabajos largos']::TEXT[], '2021-07-06T00:00:00+00:00'::TIMESTAMPTZ, '8c911e81c45b4cc0c15784842aa8a0c53fd9cf8423754385ca217b911fd35df5'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (332::BIGINT, 'Uno como estudiante tiene espectativas de que el TEC es duro, este profe cumple con eso, pero explica bien y da apoyo. Algunos se quejan aquí, pero fijo es puro resentimiento.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases excelentes', 'Exámenes retadores']::TEXT[], '2021-07-01T00:00:00+00:00'::TIMESTAMPTZ, '65424fd30d3d8f6fea924ee303f3fc454d7059771f55e17e5cabeea61d577c27'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (332::BIGINT, 'Jamás voy apoyar la idea de que profesor excelente es sinónimo de profesor que te pone a sufrir y " a aprender un montón". Es muy matado innecesariamente.'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas']::TEXT[], '2021-06-29T00:00:00+00:00'::TIMESTAMPTZ, 'b5aa1a0d61363be35bda2e5fa775c989e4c373a1e8896f2e803cc0a31ebdc51e'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (332::BIGINT, 'Debo agradecer por tener profesores como este, uno aprende mucho, pero hay que ponerle'::TEXT, 2.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-06-29T00:00:00+00:00'::TIMESTAMPTZ, 'e5e2db1b2d152327b17fb7bcb4f8e18d7539689f58a29336dc124cc691ad4749'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (332::BIGINT, 'Se ven pocos profes tan comprometidos con los estudiantes como él. Para llevar bien el curso tiene que saber administrar su tiempo. Muy recomendado.'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Tomaría su clase nuevamente']::TEXT[], '2021-06-28T00:00:00+00:00'::TIMESTAMPTZ, '0d8c99164499866d45f5c4590f82d33c493372658f18caf5b1171c15bcfff30e'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (332::BIGINT, '"Soft skills" es algo que no sólo falta en los estudiantes del TEC, si no en algunos profesores (para ejemplo este mae que piensa que el mundo gira alrededor de él y su "increíble y basto conocimiento"...)'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Exámenes retadores']::TEXT[], '2021-06-14T00:00:00+00:00'::TIMESTAMPTZ, 'd00dc8c7482801f465f6b10b454817d6dfb16bb197900adf03f05a93e49700bc'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (332::BIGINT, 'Díficil, pero se aprende mucho. Siempre está dispuesto a ayudar a los estudiantes.'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Da crédito extra']::TEXT[], '2021-06-08T00:00:00+00:00'::TIMESTAMPTZ, 'cdbe2c1a5c5e505003acad649327887cea3bf0d94ac269ec734971406cf5f465'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (332::BIGINT, 'Recibir clases de este profesor es peor que trabajar en Call Center, lleva la palabra explotación a un nivel que yo no conocía'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-05-31T00:00:00+00:00'::TIMESTAMPTZ, 'a98a0e689ec5dbe59b7e272ad516e13bb1554a7386e7d76230b041bac975b848'::TEXT, ARRAY[1020]::BIGINT[]),
    (332::BIGINT, 'Este mae es de lo peorcito que usted tiene puede topar en la U. Él piensa que el mejor estudiante es el que "se queda sin dormir 3 días y entrega un proyecto" porque eso es "compromiso" según él. No se trata de querer las cosas fáciles, se trata de no explotarse por un curso de 4 créditos.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-05-03T00:00:00+00:00'::TIMESTAMPTZ, 'c49f52bacfb3b3d7f10e0d049a2c05239fc1f69c0fa67d8cb6cb8818c9530b74'::TEXT, ARRAY[1035]::BIGINT[]),
    (332::BIGINT, 'Es cómo cuando uno come tanto dulce que queda empalagado y no quiere volver a probar azúcar en su vida. Con este profe a medio semestre ha metido tanta tarea que usted dice "no quiero volver a ver una computadora en mi vida". Muy desgastante.'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2021-04-26T00:00:00+00:00'::TIMESTAMPTZ, 'bb692ce93f0d367f9b8476e3d0a993d94f05584abd4d80e2df2d60bb950e7eb1'::TEXT, ARRAY[1035]::BIGINT[]),
    (332::BIGINT, 'Si mete con él sepa que desde el día 1 hasta el día final de semana 20 ud va a parir, si pudiera dejar tarea nueva en semana 19 lo haría.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-04-17T00:00:00+00:00'::TIMESTAMPTZ, '783aba2ed01cf661f10424908b731c58a92fefbe864a2ec43ffd64393fc8b297'::TEXT, ARRAY[1022]::BIGINT[]),
    (332::BIGINT, 'Con este mae ud no solo aprende de progra, también aprende de depresión, ansiedad, dolores de cabeza, ganas de no volver a la U, etc.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2021-04-14T00:00:00+00:00'::TIMESTAMPTZ, '8ff541b54577bf3e8e4e46b1af67c6d98f75494b1b0755ff8cd6eb53a943909f'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (332::BIGINT, 'No sean cómo yo que no hice caso a los comentarios aquí escritos y matriculé con este "profesor". El peor, no sé extrañe si a medio semestre siente ganas de dejar la U tirada.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas']::TEXT[], '2021-04-09T00:00:00+00:00'::TIMESTAMPTZ, '815cc231b6af33354a1dac51f580a4bf80cc8b4acd03cf6d344d13eba012911c'::TEXT, ARRAY[1020]::BIGINT[]),
    (332::BIGINT, 'Dejé el curso tirado debido a que la carga que este señor generaba era demasiada y sinceramente hasta en darme de baja de la U pensé, se podría decir que le agarré asco al TEC. Una psicóloga del propio TEC me dijo algo muy real "su salud mental es mejor que quedarle bien a un profe" sabias palabras.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-03-29T00:00:00+00:00'::TIMESTAMPTZ, '22148a82db6a44b5b9c2e8eba96b68f2da9db9445336d98496af95942fc643ad'::TEXT, ARRAY[1045]::BIGINT[]),
    (332::BIGINT, 'Si uno ha trabajado en el área de computación se dará cuenta que este tipo de profesores son los peores, todo lo enseñan desde el punto de vista de alguien que jamás ha salido de la universidad, haciendo las evaluaciones de forma super académicas, al final uno ni aprende de verdad.'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas']::TEXT[], '2021-03-19T00:00:00+00:00'::TIMESTAMPTZ, 'ae674b667a5b4dac72371dc86d11dc257068f8ccc237860edce0d68132065059'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (332::BIGINT, 'Meta con cualquier profe menos con este, que tortura'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas']::TEXT[], '2021-03-16T00:00:00+00:00'::TIMESTAMPTZ, '20c018a240365e8a7bf9255cbdefc89ed3906dc1e839b6f1739c4f5709e6323b'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (332::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Exámenes retadores', 'Muchos proyectos grupales']::TEXT[], '2021-03-12T00:00:00+00:00'::TIMESTAMPTZ, '617194ec863a4ffa645160971765afb3b4ffc067b81d2226e4d628418ff83714'::TEXT, ARRAY[1026, 1018]::BIGINT[]),
    (332::BIGINT, 'Ahora entiendo de dónde viene la fama del TEC de "ser cómo robots" y es gracias a profes como este, que horror'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas']::TEXT[], '2021-03-11T00:00:00+00:00'::TIMESTAMPTZ, '958af03ac1f0209be37c796255270b700387018628eee6c25fcba81518716a58'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (332::BIGINT, 'Un profesor 100% académico, cómo él lleva repasando está materia 15+ años espera que usted en 2 semanas se coma cargas de tarea increíble. Le importa un bledo su tiempo, el mae espera que ud dedique el triple de lo que los créditos piden. El peor profesor que he tenido'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Clases largas']::TEXT[], '2021-02-28T00:00:00+00:00'::TIMESTAMPTZ, '698a71158de0493391bc71e26124c46436c634390fbf4db1c33f056d7c9ae0db'::TEXT, ARRAY[1035]::BIGINT[]),
    (332::BIGINT, 'Este mae no debería dar cursos de primer ingreso, la carga académica que coloca es demasiada, cualquier sin experiencia en la U muy probablemente le pase por la cabeza dejar la U botada, si no más entrando se topa con un profesor como este. Evitarlo sería lo mejor.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas']::TEXT[], '2021-02-23T00:00:00+00:00'::TIMESTAMPTZ, 'cb0b570687a5f38349cfff785f32b4c1c56a0edfabde12c30791294969e351ea'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (332::BIGINT, 'En el TEC hay malos profes pero este mae ufff les gana por goleada.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas']::TEXT[], '2021-02-16T00:00:00+00:00'::TIMESTAMPTZ, '92cef5b5e519a9b1f9b22afe58b8a501a65b8281dc55315c881b9f18c01605d5'::TEXT, ARRAY[1045]::BIGINT[]),
    (332::BIGINT, 'Un profesor que no entiende de carga académica, prepárese para parir día y noche'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Deja trabajos largos']::TEXT[], '2021-02-14T00:00:00+00:00'::TIMESTAMPTZ, 'b0d6c013f0444b9ddae86fc145a4c0eb2f0e7c4c8d66f0a3ac1a80d609e4d6bf'::TEXT, ARRAY[1035]::BIGINT[]),
    (332::BIGINT, 'Los exámenes son innecesariamente intensos, los trabajos son largos y cargados de detalles, las clases son pesadas (para variar había un "oyente" que para lo único que servía era para jugar de inteligente junto al profesor), matricular con él es una depresión segura a medio semestre.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Deja trabajos largos']::TEXT[], '2021-02-08T00:00:00+00:00'::TIMESTAMPTZ, 'ce1456623d25fe4f8fa95c493d166169f68e4a5e812d588ec2b714d6a68f9980'::TEXT, ARRAY[1045]::BIGINT[]),
    (332::BIGINT, 'Es un curso que por si solo requiere mucho estudio. El profesor no es tan malo (si ocupas ayuda esta disponible), importante es iniciar los trabajos con tiempo porque si hay mucha carga. Para los exámenes hay que prepararse y suelen ser largos.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Exámenes retadores']::TEXT[], '2021-02-04T00:00:00+00:00'::TIMESTAMPTZ, '80461ddb34986f2bc00c16258531dbac57b03bbdac46e541be5776d79ff1cc63'::TEXT, ARRAY[1045]::BIGINT[]),
    (332::BIGINT, 'Tampoco es el súper profesor que algunos lambiscónes dicen ni tampoco un monstruo cómo mencionan otros. Solo trate de llevar la vara al día (y sí, hay que estudiar mucho más allá de lo que indica los créditos) y puede pasar el curso.'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Deja trabajos largos']::TEXT[], '2021-02-04T00:00:00+00:00'::TIMESTAMPTZ, '0c300287d39519677562ea9ca902fff5da54a49f3f6ca3414b6fcadcc3502896'::TEXT, ARRAY[1035]::BIGINT[]),
    (332::BIGINT, 'Un mae muy inteligente pero su ego es más grande, la pedagogía no la conoce, es del tipo de profesor que apela a la idea de "si los hago sufrir entonces aprenden" cosa que el profesor ha dado a entender en varias ocasiones'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas']::TEXT[], '2021-02-01T00:00:00+00:00'::TIMESTAMPTZ, '3f2098d178ac9d8a990b8cd72da4385d86f4af36834e7cd09d7761d48c9221e1'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (332::BIGINT, 'Es un excelente profe, tiene mucha paciencia y siempre está dispuesto a explicar las veces que sea necesario para que el estudiante aprenda'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Muchos proyectos grupales']::TEXT[], '2021-02-01T00:00:00+00:00'::TIMESTAMPTZ, 'c004d37ab426e751387b21e309b15428da7d16458db929caeea811a92b6fad1c'::TEXT, ARRAY[1035]::BIGINT[]),
    (332::BIGINT, 'Es una perdida de tiempo llevar con este mae, todo lo complica de más, cualquier cosita la tiene que explicar con un ejemplo más complicado que el tema en sí, lo que le cuadra es jugar de intelectual delante de un montón de estudiantes.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-01-29T00:00:00+00:00'::TIMESTAMPTZ, 'd1d49d0c4b7f30d4192dea2450f57edc938283eedd32ddbd676f64e4e3221f6b'::TEXT, ARRAY[1035]::BIGINT[]),
    (332::BIGINT, 'El curso es pasable? Sí, pero la cantidad de horas que demanda para nada son equiparables a los créditos que vale, usted se esfuerza el triple de lo necesario solo por un curso de 4 créditos y si ud lleva un semestre con más de 3 materias, bueno, a dejar uno tirado. No es justo.'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Deja trabajos largos']::TEXT[], '2021-01-27T00:00:00+00:00'::TIMESTAMPTZ, 'abe2f398736fe43db79e9551165075d77939503724e4d1c0e784b89190a4ad08'::TEXT, ARRAY[1045]::BIGINT[]),
    (332::BIGINT, 'De lo más malo que hay'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores', 'Muchos proyectos grupales']::TEXT[], '2021-01-26T00:00:00+00:00'::TIMESTAMPTZ, '5c3cd80f77e81811f9986ac6757047181399086f5209eab6a5e935cb12b62d3f'::TEXT, ARRAY[1045]::BIGINT[]),
    (332::BIGINT, 'Me llama poderosamente la atención cómo hay alumnos que defienden profesores cómo este que le dan atol con el dedo al alumno y ya lo alaban por dar más tiempo o por rehacer un examen complicadisimo. Pero bueno, es sabido que en el TEC se alaba esa mentalidad de "si no dormís en 3 días sos campeón"'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-01-24T00:00:00+00:00'::TIMESTAMPTZ, '89add3d04391de18922305646b924700413aa90e47d56b69d171dfe379354782'::TEXT, ARRAY[1045]::BIGINT[]),
    (332::BIGINT, 'Sin duda es uno de los mejores profes que he tenido en el Tec, siempre está dispuesto a ayudar. A mi me da mucha cólera con los compañeros que se quejan de todo, pero en realidad es un profe excelente, si uno no entiende algo él siempre trata de buscar otra manera de explicarnos.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-01-22T00:00:00+00:00'::TIMESTAMPTZ, 'f14318247510d758fb477bded2d3de9eb0e3b6846e47f2d0a5159b03132c3f14'::TEXT, ARRAY[1045]::BIGINT[]),
    (332::BIGINT, 'A los nuevos ingresos les recuerdo que la matrícula extraordinaria es 2 días después de la normal, sirve para meter en otras sedes y con otros profes, no se embarquen metiendo con este compa, todo es más difícil en comparación con otros profesores.'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-01-21T00:00:00+00:00'::TIMESTAMPTZ, '372deed7fb0055b472ede943f5b552f58666c588756c330a3a0b46afeb1cf85f'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (332::BIGINT, 'De pedagogía no tiene un pelo. Altanero y cuadrado.'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Deja trabajos largos']::TEXT[], '2021-01-21T00:00:00+00:00'::TIMESTAMPTZ, '746dac1a8b636de46ef3e8d2dabb0c8c41ebfc79b728de9876f2be8190d1e1ef'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (332::BIGINT, 'Aunque el profe sea duro y todo, me parece muy poco profesional q muchos se quejen de él de forma irrespetuosa y lo ataquen ya que saben que el profe revisa estos comentarios. Deberían decirle las cosas a él, porque hablando se entiende la gente y no andar difamándolo. Si de vdd quiere aprender llev'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Exámenes retadores']::TEXT[], '2021-01-21T00:00:00+00:00'::TIMESTAMPTZ, '5dc8eb90930ad7f0eb5db09a7dffa70267913aa6fa3c1c786771b6491e1360c2'::TEXT, ARRAY[1045]::BIGINT[]),
    (332::BIGINT, 'Es cómo los políticos, lo hace mie*** a uno y después le da un discurso de porque lo que hizo está súper justificado y que más bien hay que agradecerle. Meta con cualquier profe menos este.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Exámenes retadores']::TEXT[], '2021-01-18T00:00:00+00:00'::TIMESTAMPTZ, 'd38b60511a6ab16caf587c746004146ce2abd7e5afabecbe8393c2c0308a7c5e'::TEXT, ARRAY[1045]::BIGINT[]),
    (332::BIGINT, 'Un mae que se cree la cereza del pastel, fijo terminó siendo profesor porque en ninguna empresa se lo aguantan con ese ego.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Exámenes retadores']::TEXT[], '2021-01-16T00:00:00+00:00'::TIMESTAMPTZ, 'ea46acdb0393dfa8860ae7470fba8f595a8bfecc3ed8e1910f50984910520022'::TEXT, ARRAY[1035]::BIGINT[]),
    (332::BIGINT, 'El periodo mas corto de vacaciones del TEC por causa del TEC arruinado por alguien del TEC estrés continuo en todo momento. No entiende que encerrados el nivel de estrés aumenta y deja cosas que si uno no saca tiempo de vacaciones no va lograr terminar a tiempo. Muy desconsiderado.'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('55','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2021-01-13T00:00:00+00:00'::TIMESTAMPTZ, 'deafdd535e527d432d00fef49bac2b94667349ed4550d3bbb4fc85e6932be021'::TEXT, ARRAY[1045]::BIGINT[]),
    (332::BIGINT, 'Dada la naturaleza del curso se tornó llevadero, sin embargo, el profesor es muy cuadrado, las varas son solo cómo él dice y punto además de que su ego y altanería lo hacen un tanto insoportable, lo cual provocaba que la clase se volviera tediosa'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Clases largas']::TEXT[], '2021-01-11T00:00:00+00:00'::TIMESTAMPTZ, 'b1a894d08d79521e17044eaa9cbee27180ae11b83ef2c344877c71b680d83651'::TEXT, ARRAY[1151]::BIGINT[]),
    (332::BIGINT, 'Deja trabajos muy largos y elaborados y no ayuda en casi nada. Las clases son aburridas.'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2021-01-10T00:00:00+00:00'::TIMESTAMPTZ, 'd794ec47c8c58e7500446fd06672f8fec2c94167a55061bb6799212e6782fd00'::TEXT, ARRAY[1045]::BIGINT[]),
    (332::BIGINT, 'Este profe habla de eficiencia todo el tiempo aunque es difícil entender. Da chance de entregar trabajos tarde'::TEXT, 2.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Da crédito extra']::TEXT[], '2021-01-09T00:00:00+00:00'::TIMESTAMPTZ, '40fd125105c83cdbfa22a537012d4fa3728ff050c36e8db57b2f6693429ec316'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (332::BIGINT, 'Por profesores cómo este es que el TEC tiene tanta deserción el primer semestre, profes que solo le quitan a uno las ganas de estudiar compu, lo hacen sentir que uno es un inútil, que si ud no está dispuesto a dejar su vida personal por un simple curso entonces ud es un mediocre.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Deja trabajos largos']::TEXT[], '2021-01-07T00:00:00+00:00'::TIMESTAMPTZ, '2a0f9ea4222f8fb031b34aa2c5c63ea98bdc4218108b52e1b124aa95ad362ce3'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (332::BIGINT, 'Asco de profesor, es un explotador'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Exámenes retadores']::TEXT[], '2020-12-30T00:00:00+00:00'::TIMESTAMPTZ, 'c2fc33795cd1a874ee67c99ecdf9dcab1bee70a2503b946d8a0379684a394530'::TEXT, ARRAY[1022, 1020]::BIGINT[]),
    (332::BIGINT, 'No entiendo el afán del mae por joder al estudiante, en serio parece que quiere que uno deje la materia morir. Entiendo que esto es el TEC y que es difícil, pero este pseudo-profesor no respeta que su curso vale 4 créditos, no 10. Exámenes imposibles+progras larguísimas+tareas exageradas...'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Exámenes retadores']::TEXT[], '2020-12-27T00:00:00+00:00'::TIMESTAMPTZ, '09c19315156332ecd8101c8ef08d46928bc00297018d8a42752f92445485c175'::TEXT, ARRAY[1022, 1020]::BIGINT[]),
    (332::BIGINT, 'Cuando uno compara al profe Eddy con otros profes del mismo curso ya sea hablando con amigos o así, se da cuenta que es increíblemente más complicado todo, se encarga de complicarle la vida al estudiante de manera innecesaria, parece que quiere que uno se rinda o sacrifique todo por quedarle bien'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Deja trabajos largos']::TEXT[], '2020-12-22T00:00:00+00:00'::TIMESTAMPTZ, 'f4d35009fb67357c94584c5842087b97aad2ad6651d87848b84ee09ad23e96e1'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (332::BIGINT, 'Dejó un proyecto ENORME para "vacaciones" y hay que entregarlo justo al entrar, tenemos que pasar todas las vacas haciendolo porque a él le roncó hacer 4 proyectos en el semestre. Cómo dijo un comentario más abajo, "el mae se pasa por el cu** el tiempo del estudiante" y cree que uno es un robot'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2020-12-17T00:00:00+00:00'::TIMESTAMPTZ, 'ce0c6d621dce28c3871e8530283258a041a5fc222a494a489cee05aeb4a7e1e3'::TEXT, ARRAY[1045]::BIGINT[]),
    (332::BIGINT, 'Demasiada la carga, difícil entender su clase, lo hace sonar más complicado que lo que es, además entre él y el oyente(que habla más que cualquier otro) lo terminan de confundir mas a uno, razón por la que 2/3 de su clase abandonó. Haga caso.. ESCAPE!!'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2020-12-16T00:00:00+00:00'::TIMESTAMPTZ, '64ce26eef9cd7d3126f7480c04b5908623c07a72529941c1ad9bc372514c4049'::TEXT, ARRAY[1045]::BIGINT[]),
    (332::BIGINT, 'A pesar de saber que por culpa del TEC solo vamos a tener 1 mes de "vacaciones" y el 1er semestre del 2021 empieza justo terminar este, espera que pasemos con su proyecto en vacas. Deberían ser fechas donde nos relajábamos, pero al parecer eso no le importa siempre y cuando se haga lo que el dice...'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('50','')::SMALLINT, NULL::SMALLINT, ARRAY['Deja trabajos largos', 'Exámenes retadores', 'Muchos proyectos grupales']::TEXT[], '2020-12-16T00:00:00+00:00'::TIMESTAMPTZ, '0315e768ad86c0c2e86a59517e364049d2781a3b12d4f4cbb62746dfaf9090e4'::TEXT, ARRAY[1045]::BIGINT[]),
    (332::BIGINT, 'La plata que gasté matriculando con este compa mejor la hubiera gastado en chicles. Innecesariamente complicado este tipo'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Exámenes retadores']::TEXT[], '2020-12-10T00:00:00+00:00'::TIMESTAMPTZ, '91949eb9b26edf2e60d19e8da6585380bdfddb102efeaad4a673a5ae24b86608'::TEXT, ARRAY[1035]::BIGINT[]),
    (332::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Exámenes retadores']::TEXT[], '2020-11-26T00:00:00+00:00'::TIMESTAMPTZ, 'f0dd59e93c9072fb646a8c4896abe42c1d895602935ced06c5e603f0bbeba30f'::TEXT, ARRAY[1045]::BIGINT[]),
    (332::BIGINT, 'Excelente profe, se preocupa mucho por la opinión de los estudiantes, explica muy bien y es un genio programando. He aprendido mucho con él, recomendado'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Inspirador', 'Brinda apoyo']::TEXT[], '2020-11-25T00:00:00+00:00'::TIMESTAMPTZ, 'c595579f4848ec7bd3bc99c48aecd6b26390f6ca9bcdf8be609eec2aed888f49'::TEXT, ARRAY[1045]::BIGINT[]),
    (332::BIGINT, 'Es un excelente profesor, explica un tema hasta el cansancio hasta poder entenderlo y comprenderlo aunque deja bastantes tareas estos no tienen mucha calificación y es solo de practica. Sus proyectos son difíciles pero no imposibles, claro si administra bien su tiempo y no trabaja una semana antes.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-11-25T00:00:00+00:00'::TIMESTAMPTZ, '3d09bd96a41eebfada96c0bec07f07e624bce74cf54911db2837204fb76dd520'::TEXT, ARRAY[1045]::BIGINT[]),
    (332::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Exámenes retadores']::TEXT[], '2020-11-25T00:00:00+00:00'::TIMESTAMPTZ, '45619bbf95ba3840a2505187525c22284a15b3f46a9259ae466f3ff168a50150'::TEXT, ARRAY[1045]::BIGINT[]),
    (332::BIGINT, 'El man se pasa por el cu** el tiempo del estudiante, pretende que uno viva, almuerce y sueñe con el curso de él. Un claro ejemplo: un día antes de iniciar el semestre nos contacto para decirnos cual sería la primera tarea. Un profesor que espera que ud se dedique a su curso de día y de noche.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos']::TEXT[], '2020-11-21T00:00:00+00:00'::TIMESTAMPTZ, '76a48ea2ad060079b87e5a3c51fee9ab7e6de712283ea22dc05d2c1d5dde5fcd'::TEXT, ARRAY[1045]::BIGINT[]),
    (332::BIGINT, 'Jamás voy a entender porque el TEC contrata profesores con bases pedagógicas NULAS. Este señor no sabe darse a entender y todo lo quiere para ya.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas']::TEXT[], '2020-11-19T00:00:00+00:00'::TIMESTAMPTZ, '5943ee2991ebe6363de18de4dc6766d0fe5cae07cfb98ebf4cd3ad63b6cd77a3'::TEXT, ARRAY[1045]::BIGINT[]),
    (332::BIGINT, 'Es un creído cómo ningún otro, el mismo mae en clases se deja llevar diciendo que en el TEC las cursos deberían ser mucho más severos y que la educación en este país es una basura (cómo si él fuera un súper profe...). Cómo profesor un horror y cómo persona un asco.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas']::TEXT[], '2020-11-15T00:00:00+00:00'::TIMESTAMPTZ, 'f15cace6a70142c0d0ddb21401aa534b830d9f29bac9d9a195bc31d8d2fd509e'::TEXT, ARRAY[1045]::BIGINT[]),
    (332::BIGINT, 'Recibir clases con este mae es cómo que CR7 venga y te diga "tome, haga 100 tiros libres y todos los tiene que hacer al ángulo y perfectos si no entonces ud es un inútil que no merece estar aquí" un profesor que lo único que logra en el estudiante es tener ganas de dejar la carrera botada.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Exámenes retadores']::TEXT[], '2020-11-09T00:00:00+00:00'::TIMESTAMPTZ, '6a13af35f8832986670e125e281b45a8ac059792e6c83c931bd0215950eb5cf7'::TEXT, ARRAY[1045]::BIGINT[]),
    (332::BIGINT, 'El profe con 10 años de experiencia espera que uno con 1 semana ya programe tareas y proyectos súper rápido y súper fácil a cómo él lo hace por ende los trabajos son demasiado pesados y él los complica de más. Meter con este mae es un error'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas']::TEXT[], '2020-11-04T00:00:00+00:00'::TIMESTAMPTZ, '7e6fcf9a9424f5fdb22074e940cc396afe3664c4118e91dc72314aa19a979b3a'::TEXT, ARRAY[1045]::BIGINT[]),
    (332::BIGINT, 'Eddy es ese tipo de profesor que piensa que complicando la materia lo más posible uno "aprende más" cuando al final uno ni aprende y sólo pasa noches sin dormir para poder rendir en el curso.'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2020-10-25T00:00:00+00:00'::TIMESTAMPTZ, 'a8215af985ebbbf092e96972d4cc1c377b64631a1bf6c97234705fe97d1c1d26'::TEXT, ARRAY[1045]::BIGINT[]),
    (332::BIGINT, 'Con Eddy sólo existe una solución y una forma de programar, la suya y nada más. Ni invente tratar de programar diferente o ser creativo. Demasiado cuadrado.'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Deja trabajos largos']::TEXT[], '2020-10-16T00:00:00+00:00'::TIMESTAMPTZ, '72f0e8f3db17c16ad2490757f2f4795458a3df04c92b9f078eae44d4bc4407e2'::TEXT, ARRAY[1035]::BIGINT[]),
    (332::BIGINT, 'Antipático y pesado, además de que tiene marcadas preferencias entre los alumnos que ya él conoce de cursos pasados. Por otro lado, se pasa con los trabajos que deja y su defensa es - yo esto lo hago en 20 minutos, por qué uds no?-'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas']::TEXT[], '2020-10-14T00:00:00+00:00'::TIMESTAMPTZ, '681a0da341d1a7729c47a291fd13c21bf3745362cc8411727069d049c769b9f7'::TEXT, ARRAY[1045]::BIGINT[]),
    (332::BIGINT, 'Siempre que ud lea "si quiere aprender matricule con él" es sinónimo de "el profesor piensa que su materia es la única y le va meter tarea por todo lado". Este tipo de profesores son los que hacen que el TEC tenga ese terrible estigma de "buen estudiante = persona que vive para la U y nada más".'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas']::TEXT[], '2020-10-04T00:00:00+00:00'::TIMESTAMPTZ, '10c677fa570a5af9522137e54b776ab5103b85c6d797bc3c8ba54b3324deb054'::TEXT, ARRAY[1151]::BIGINT[]),
    (332::BIGINT, 'En realidad hace un par de años llevé un curso con él y en ese entonces yo pensaba que él era "mal profe" debido a que era un poco egocéntrico pero en realidad no es así y solo hay que poner esfuerzo y atención a las clases para pasar el curso. Si usted quiere aprender realmente, matricule con él.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2020-09-23T00:00:00+00:00'::TIMESTAMPTZ, '059eb2a62e6edef42ec39e24f2dc1d9a311a761e2c8ccbedfc1281ed02a70c0b'::TEXT, ARRAY[1151]::BIGINT[]),
    (332::BIGINT, 'El profesor no ha caído en cuenta que él está dando clases, por ende, las personas están aprendiendo y no vienen ya con los conocimientos aprendidos. Da por hecho que uno domina lo que él domina y basado en eso deja trabajos excesivamente fuertes mientras dice "esto se hace en 2 días". Huya.'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas']::TEXT[], '2020-09-13T00:00:00+00:00'::TIMESTAMPTZ, 'b582c6f3f2ce0ff9814a4de4b8d671f095527f9e36e7840aa56ff56ec8f40a11'::TEXT, ARRAY[1035]::BIGINT[]),
    (332::BIGINT, 'El profesor es bueno, bastante egocéntrico eso sí pero bueno, es llevadero. Mi problema con él es que piensa que dejando toneladas de tarea y cosas complicadas el estudiante va "aprender más" cuando en realidad uno termina saturado de información y sin ganas de volver a clases.'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas']::TEXT[], '2020-09-10T00:00:00+00:00'::TIMESTAMPTZ, 'eaff7c9cfc093c3b71ec47b1e556f524c66d7ede958278db01837207d15c1973'::TEXT, ARRAY[1035]::BIGINT[]),
    (332::BIGINT, 'El mae sabe mucho, pero le gusta creer que es superior a todo mundo, la palabra humildad no la conoce y no sabe cuando cerrar la boca.'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2020-09-02T00:00:00+00:00'::TIMESTAMPTZ, '88247368d513f4a266f5ed73b845d438d67a611109f4c1764289451e218ff5c3'::TEXT, ARRAY[1045]::BIGINT[]),
    (332::BIGINT, 'Se ve que sabe mucho, pero es de esos profesores que no saben dar clases, cree que regodearse y humillar al estudiante es dar clases, por lo mismo es difícil pedirle ayuda, porque si él considera que la pregunta es tonta prepárese para la humillada'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clase fácil']::TEXT[], '2020-08-26T00:00:00+00:00'::TIMESTAMPTZ, 'ec38e93b27711f58a6a156b8e67ca2a056f75b3fcea2d8349804fe8e715e349f'::TEXT, ARRAY[1045]::BIGINT[]),
    (332::BIGINT, 'Es muy buen profe, el problema es que nadie presta atención a sus clases y salen mal en las asignaciones, culpando al profe que no explica bien.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Exámenes retadores', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-17T00:00:00+00:00'::TIMESTAMPTZ, 'ded414d3a52a054342a9be0ed3eefb330186f554e6517cd70038e49143da0d24'::TEXT, ARRAY[1151]::BIGINT[]),
    (332::BIGINT, 'Inicialmente en la carrera sus cursos eran muy complicados, yo notaba poco interés con los estudiantes, pero ahora siento que era yo que no le daba suficiente interés a sus clases, pues con las clases virtuales y al inicio del 2020 cuando no lo eran, noté su interés por enseñar y que quedara claro.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2020-06-30T00:00:00+00:00'::TIMESTAMPTZ, '1a518642aed06d3804f04595e7e2b70f3b6500cffd7bf8119c9df18512864ca9'::TEXT, ARRAY[1045]::BIGINT[]),
    (332::BIGINT, 'Es un profesor apasionado por el aprendizaje de sus estudiantes, en muchas ocasiones la gente no lo entiende o malinterpreta el porqué dice o hace las cosas, por esta razón incluso dicen que tiene un grupo de favoritos, pero solamente es la gente que está realmente dando un esfuerzo por el curso.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2020-06-16T00:00:00+00:00'::TIMESTAMPTZ, 'a39503d74ecb9a1c32fe4a9dd56b8c234e58a7860c1fecbfa285f500ed18d780'::TEXT, ARRAY[1035]::BIGINT[]),
    (332::BIGINT, 'Es de los profesores más juegas de vivos qué hay. Sabe mucho pero cree que el resto son unos idiotas y solo el sabe. Deberían conseguir profes que sepan de pedagogía y que no anden buscando simplemente llevar su ego. Es un engreído y paso como profesor.'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-02-23T00:00:00+00:00'::TIMESTAMPTZ, 'eb88d95b185f22877341a66759b255c9eb7f5e9ca5ca1a2244143b3f6f806850'::TEXT, ARRAY[1035]::BIGINT[]),
    (332::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('45','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Exámenes retadores']::TEXT[], '2019-07-26T00:00:00+00:00'::TIMESTAMPTZ, '1ff8c647195458a4019857f6352baf4aca9c0993bc9ec061e6880261cae4d7e2'::TEXT, ARRAY[1035]::BIGINT[]),
    (332::BIGINT, 'Es un profesional excepcional, con mucho conocimiento y que realmente se esfuerza por que los estudiantes piensen por sí mismos. Si bien es cierto en ocasiones su frustración lo lleva a tratar de manera un poco tosca al estudiante, la mayoría del tiempo lo hacen en forma de broma.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muy cómico', 'Exámenes retadores']::TEXT[], '2019-05-29T00:00:00+00:00'::TIMESTAMPTZ, '7fa7de11f264422e3030b4a27a4a88e39aa15828e718a4d987df46727a26a2be'::TEXT, ARRAY[1249]::BIGINT[]),
    (332::BIGINT, 'Un profesor muy competente, lo cual lo hace difícil, ya que, lo que pretende es enseñar para formar a profesionales con la capacidad de saber poner en práctica lo aprendido. Sin embargo, debería saber que no todos manejamos lo "basico" o lo "obvio". Estimula y ayuda mucho al estudiante.'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-05-29T00:00:00+00:00'::TIMESTAMPTZ, '6f89062366165f7c7b4a7acaee0dcadd306816859332dbd8c696b46287ae7b0a'::TEXT, ARRAY[1249]::BIGINT[]),
    (332::BIGINT, 'Claramente a nivel nacional es fácilmente el profesor de la carrera de ingeniería en computación que presenta mayor nivel, es una persona crítica, demuestra interés por enseñar más que solo números. Sin embargo, es egocéntrico... Difícilmente se le comprende, solo se escucha a sí mismo.'::TEXT, 2.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-05-28T00:00:00+00:00'::TIMESTAMPTZ, 'b2f0a7b8f5a22d8a997ddeb9c48bc16379b3e7bc7bcae37de944339a5adba2f9'::TEXT, ARRAY[1249]::BIGINT[]),
    (332::BIGINT, 'Es un profesor pésimo en pedagogía y didáctica. Este asume que los estudiantes deben saber lo que el sabe y no es así. Por esta razón el va a un nivel superior que los estudiantes y así no se puede alcanzar un aprendizaje. Se preocupa mas por satisfacer su ego que el aprendizaje de los Estudiantes.'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2019-05-28T00:00:00+00:00'::TIMESTAMPTZ, '459af1e2718ac8815c864f06ff6ab88d7e511ac7603998770599177fe68b4b5a'::TEXT, ARRAY[1249]::BIGINT[]),
    (332::BIGINT, 'El plátano es una excelente fuente de potasio'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-05-28T00:00:00+00:00'::TIMESTAMPTZ, '25ce610772824d166470f8c6b52b42486105cdc53c0f0f1a060a86c4cc4be3a6'::TEXT, ARRAY[1249]::BIGINT[]),
    (332::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY['Exámenes retadores']::TEXT[], '2019-05-09T00:00:00+00:00'::TIMESTAMPTZ, 'a5e73bd031167accdd54706ed385a847e37d1387e1e7bcb700bb8c20b4547878'::TEXT, ARRAY[1035]::BIGINT[]),
    (332::BIGINT, 'Le gusta humillar a los estudiantes y mofarse de ellos'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2019-05-09T00:00:00+00:00'::TIMESTAMPTZ, '62ebf0924065f9fab40cb96cc2c6acebca6872789a13d29be4a94380692f1e08'::TEXT, ARRAY[1035]::BIGINT[]),
    (332::BIGINT, 'Es un profesor que se cree superior a los estudiantes, inclusive hasta aveces los humilla con comentarios despectivos, y hacer sentir al estudiante que no sabe nada.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Exámenes retadores']::TEXT[], '2019-05-09T00:00:00+00:00'::TIMESTAMPTZ, 'a7eb355c0ce540c2e9c9538e229ba7868d9dea79d64c59626236aab9135a4a32'::TEXT, ARRAY[1035]::BIGINT[]),
    (332::BIGINT, 'El es un buen profe, pero a veces se enfoca en cosas que no son muy propias del curso'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('40','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Requiere mucha lectura', 'Clases excelentes']::TEXT[], '2019-02-05T00:00:00+00:00'::TIMESTAMPTZ, '594b76550b0583d054f54b30a812da1a85ce9ca9161ecf0826fd8bcbd517561d'::TEXT, ARRAY[1035]::BIGINT[]),
    (332::BIGINT, 'Excelente profesor, es exigente por lo que se aprende demasiado y se aprende muy bien, además las clases son bastante entretenidas. Sin duda de los mejores.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2018-06-20T00:00:00+00:00'::TIMESTAMPTZ, 'c1141b959779f016dee7782f63df037c534214799a399123936c376ff83c0181'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (332::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Exámenes retadores']::TEXT[], '2018-06-20T00:00:00+00:00'::TIMESTAMPTZ, '3358a3aa189270aa6dcc7e1db0b4001ff4495bea3cd53bc5d43fe031c0529652'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
    (332::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo', 'Exámenes retadores']::TEXT[], '2018-06-20T00:00:00+00:00'::TIMESTAMPTZ, 'b6bf7148842cd1319f3833850531183e35c71a92af3c2410771532758634c3cf'::TEXT, ARRAY[1020]::BIGINT[]),
    (332::BIGINT, 'Es un poco exigente pero sus clases son muy buenas y cualquier duda del curso o no siempre está dispuesto a contestarla.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Exámenes retadores']::TEXT[], '2018-06-05T00:00:00+00:00'::TIMESTAMPTZ, '59dd2f1b82029d572a2d925ab613ea85c9bdcbd2a6854a711cc4283394916424'::TEXT, ARRAY[1020, 1022]::BIGINT[]),
