    (332::BIGINT, 'TIENE TODAS LAS DEBILIDADES!! xD'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Exámenes retadores']::TEXT[], '2017-06-27T00:00:00+00:00'::TIMESTAMPTZ, 'e8ce75b47e0af7d64f18b5618ae10054366c9ac7b27f3cafa837fc03154eaf25'::TEXT, ARRAY[1017]::BIGINT[]),
    (332::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-27T00:00:00+00:00'::TIMESTAMPTZ, 'c703eada70d7330f5d5fd01b76c5e3f4641557f3e5c465ad33cb0dbcc5f50082'::TEXT, ARRAY[1017]::BIGINT[]),
    (332::BIGINT, 'Se desempeña bien en clase y los contenidos pero las exigencias son altas'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Respetado por los estudiantes', 'Aspectos de calificación claros']::TEXT[], '2017-06-20T00:00:00+00:00'::TIMESTAMPTZ, '432c8078343c361d5d97fb2a955378bd22bfa197ee76491d34578ab3a3c5ccb8'::TEXT, ARRAY[1017]::BIGINT[]),
    (332::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Tomaría su clase nuevamente']::TEXT[], '2017-06-20T00:00:00+00:00'::TIMESTAMPTZ, 'f8cb6954c36775e9166f99465593746a11e8e082b8eed5cba74bd70a25a5b5ad'::TEXT, ARRAY[1017]::BIGINT[]),
    (332::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Exámenes retadores']::TEXT[], '2017-01-18T00:00:00+00:00'::TIMESTAMPTZ, 'b5c7497ac8ae6a46d3a1de5935584ac8f1a0f8d4a6b7014d9346b1118bebb53c'::TEXT, ARRAY[1035]::BIGINT[]),
    (332::BIGINT, 'Eddy es muy bueno. Da las bases del curso y depende de usted, como todo curso. Hay que esforzarse demasiado, pero es el mejor para el curso, los otros profes que dan el curso son de mentirita y muy MALOS.'::TEXT, 2.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Muchas tareas']::TEXT[], '2016-12-11T00:00:00+00:00'::TIMESTAMPTZ, '5d40584d461ca32f0e0cce1d58aac226fa4ae885320b97853ca752d85c7b9728'::TEXT, ARRAY[1035]::BIGINT[]),
    (332::BIGINT, 'Tiene mucho conocimiento pero como profesor no sabe bien transmitirlo. Lo bueno es que él resuelve dudas si es necesario hacerlo y por lo general da puntos extra para poder pasar sus cursos.'::TEXT, 2.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Da crédito extra', 'Exámenes retadores']::TEXT[], '2016-12-07T00:00:00+00:00'::TIMESTAMPTZ, 'd21e17fe39fae9cf3423e7329c527b053a947df45cfe39375aa4426f0d48a680'::TEXT, ARRAY[1035]::BIGINT[]),
    (332::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Brinda apoyo', 'Exámenes retadores']::TEXT[], '2016-07-03T00:00:00+00:00'::TIMESTAMPTZ, '51fdd626687376f7c63c369aee31a6ceec7641efa4905174d4303b6202d76930'::TEXT, ARRAY[1035]::BIGINT[]),
    (332::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Clases excelentes', 'Exámenes retadores']::TEXT[], '2016-07-01T00:00:00+00:00'::TIMESTAMPTZ, '03ebd83e2510f3f562c3bb93e4a088c6a85409cc1efd6f43193ed785f5654976'::TEXT, ARRAY[1035]::BIGINT[]),
    (332::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-30T00:00:00+00:00'::TIMESTAMPTZ, '4b79c7835105f6945fef3c1e737f4276d7ab5563542bb80181373a20747b9dcd'::TEXT, ARRAY[1017]::BIGINT[]),
    (332::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Clases excelentes', 'Exámenes retadores']::TEXT[], '2016-06-30T00:00:00+00:00'::TIMESTAMPTZ, '5ab2e923fb207729fa00a597222f913e6e4bfaf4b149702a352f168abec49e3f'::TEXT, ARRAY[1035]::BIGINT[]),
    (332::BIGINT, 'Debes mostrar interés por aprender e intentar realizar todos los trabajos y proyectos.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Respetado por los estudiantes', 'Tomaría su clase nuevamente']::TEXT[], '2016-06-30T00:00:00+00:00'::TIMESTAMPTZ, '974cc6564174444a7fe2fdba43744c0bb3c054d6d5d8d0ded17d798839655414'::TEXT, ARRAY[1035]::BIGINT[]),
    (332::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('50','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Clases excelentes', 'Exámenes retadores']::TEXT[], '2016-06-30T00:00:00+00:00'::TIMESTAMPTZ, 'eeca19191072c678bf81bb3636c32a74aa6805374dd0f03c91310ffeb1e6c3c0'::TEXT, ARRAY[1017]::BIGINT[]),
    (332::BIGINT, 'Excelente profesor, una persona muy correcta y le gusta enseñar tanto como la Computación. No tiene problema con preguntas fuera de clase y durante. Su claridad en explicar y ejemplos podrían ser más claros pero el estudiante debe esforzarse.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('55','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Respetado por los estudiantes']::TEXT[], '2016-06-30T00:00:00+00:00'::TIMESTAMPTZ, '7d935a46048e278fead63ca108e3dce83ffc40d23c96239ee9d4ab318218f1f1'::TEXT, ARRAY[1035]::BIGINT[]),
    (332::BIGINT, 'Hace un curso dónde brinda al estudiante oportunidades de pasar'::TEXT, 2.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Exámenes retadores', 'Tomaría su clase nuevamente']::TEXT[], '2016-06-30T00:00:00+00:00'::TIMESTAMPTZ, '9e84d5c1325879d07490476cf50a3c59196c6d826a4e03e60ff2097842a7d1bc'::TEXT, ARRAY[1035]::BIGINT[]),
    (332::BIGINT, 'En sí no es un mal profesor pero él pretende que el estudiante investigue gran parte de la clase por su cuenta y deja temas al aire, además suele divagar en clase.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('55','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-16T00:00:00+00:00'::TIMESTAMPTZ, '5bdbb6ddc26a79ea1104be604133aee7bd619c8fb61a7795f8045a1b369f0a23'::TEXT, ARRAY[1162]::BIGINT[]),
    (332::BIGINT, 'Buen profesor, sin embargo deja temas al aire y asume que el estudiante sabe de lo que él está hablando. Exige mucho pues él sabe que el estudiate puede dar más.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-03T00:00:00+00:00'::TIMESTAMPTZ, '628a3e5907b0f383320fabdf28b0ab3d2a6df5834fd315613abee07be8257ab6'::TEXT, ARRAY[1035]::BIGINT[]),
    (332::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-05-28T00:00:00+00:00'::TIMESTAMPTZ, '562bec62c155436ae03e62c2cf8a03fdf0c7d40372f12ee38781f739b20e50ba'::TEXT, ARRAY[1045]::BIGINT[]),
    (332::BIGINT, 'Es un profe muy buena gente y tiene un amplio dominio en la materia. Además las clases no son para nada aburridas, muchas llegan a ser divertidas, el único curso en el cual no me daban ganas de dormir. Deja tareas difíciles pero realizables en las que uno refuerza los conocimientos de la materia.'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-01-23T00:00:00+00:00'::TIMESTAMPTZ, '82c86621728ed3dd6666823f04d5c24159ee569c6f5b9245132a1e1d4255b6f4'::TEXT, ARRAY[1045]::BIGINT[]),
    (332::BIGINT, 'Se aprende muchísimo. Él sabe que los estudiantes pueden dar un 100% pero prefiere pedirles un 10000%. A veces llega a intimidar con su peculiar sarcasmo. Si matricula con Eddy no se va a arrepentir, nada más asegurese de contestar inteligentemente o podría pasar a ser parte de sus anecdotas!!!'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-01-16T00:00:00+00:00'::TIMESTAMPTZ, '984b5ecae2ab7c139c57d0ae3be6398c0a1dec895e9f6fa281884c6e65f96836'::TEXT, ARRAY[1045]::BIGINT[]),
    (332::BIGINT, 'Buen profesor pero, deja muchas cosas al aire cuando explica en clase y asume que el estudiante sabe de lo que está hablando, da la intención de no querer atender dudas.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-19T00:00:00+00:00'::TIMESTAMPTZ, 'ade613f906991d541be65f6a7b230c2298ba8c3fa92c8f5ab1bc65a3cbc3c388'::TEXT, ARRAY[1035]::BIGINT[]),
    (332::BIGINT, 'Excelente como Profesor y Persona, es un gran ejemplo para sus colegas y estudiantes. Realmente demuestra el aprecio que tiene por su profesión, lo cuál de forma indirecta crea un modelo a seguir en algunos de sus estudiantes. Sinceramente es un gusto estar en su clase, aún cuando se reprueba. :('::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-19T00:00:00+00:00'::TIMESTAMPTZ, 'ab820d69e7eada227a219e42b8ccf5c1c9db34729342c8d36ff79fc07fa12261'::TEXT, ARRAY[1035]::BIGINT[]),
    (332::BIGINT, 'Le encanta lo que hace, eso motiva a los estudiantes.Además se preocupa por los estudiantes, siempre aclara dudas.Para hacerla toda es una teja y siempre mantiene un ambiente de confianza.'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-18T00:00:00+00:00'::TIMESTAMPTZ, '583b35831d9cf7bc1cf1e1eebc950ec084a98aee5b6c7477047f11da27e243d4'::TEXT, ARRAY[1045]::BIGINT[]),
    (332::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-18T00:00:00+00:00'::TIMESTAMPTZ, '1dc0c788d6b4a0bb34e1bcc66ec8da1588d080e58a5f1cc568331c54db625e7e'::TEXT, ARRAY[1035]::BIGINT[]),
    (332::BIGINT, 'Ama lo que hace, tal vez puede llegar a caer un poquito mal, pero excelente profesor de programación. Sus proyectos son algo complicados, pero no imposibles y es flexible. Como profesor de matemática es un excelente profesor de programación.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-18T00:00:00+00:00'::TIMESTAMPTZ, '5f161d51e0667a750308d250dae618668629bd3454f4537dba106effb46c65ae'::TEXT, ARRAY[1045]::BIGINT[]),
    (332::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-18T00:00:00+00:00'::TIMESTAMPTZ, '72aacd139b659bed6030ec3c3dc47299096da973283ab17aa8d497f64a520728'::TEXT, ARRAY[1035]::BIGINT[]),
    (332::BIGINT, 'Elogio su compromiso social, aunque en algumos aspectos se excede!!!'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-18T00:00:00+00:00'::TIMESTAMPTZ, '4764e13d8b69bc1e08f6e9b1a801d2a687f2169b58d8a5a54ce097e6f4dee8b5'::TEXT, ARRAY[1035]::BIGINT[]),
    (332::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-18T00:00:00+00:00'::TIMESTAMPTZ, '4b43d575af15074e68aac8e133ef46ee41ae4a42cf07655c068f0fdcb20038e2'::TEXT, ARRAY[1035]::BIGINT[]),
    (332::BIGINT, 'Le interesa mucho que el estudiante realmente aprenda sobre el curso que el está impartiendo y transmite su energía. Es un algo bromista.'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-18T00:00:00+00:00'::TIMESTAMPTZ, 'b9ed9a518b98fe233c7359547c2a41b153f73d31142d7856e06374692cd1e9c0'::TEXT, ARRAY[1035]::BIGINT[]),
    (332::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-18T00:00:00+00:00'::TIMESTAMPTZ, 'adfb6458b9e312831fe3694a9fb229c8c4d48aa8a8fc084e8af2e03e30b8b123'::TEXT, ARRAY[1035]::BIGINT[]),
    (332::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-18T00:00:00+00:00'::TIMESTAMPTZ, 'f4ff7cc11a72d3681a0d22e2c8ff68db2d0b8ba64870883f0d6310a143f0b2a0'::TEXT, ARRAY[1035]::BIGINT[]),
    (332::BIGINT, 'Un profe que disfruta dar clases y se preocupa por transmitir el conocimiento. Falta retroalimentación con el estudiante en cuanto a trabajos realizados (entrega de quices y tareas). A veces no prioriza los contenidos del curso como debería, pero en general, un buen profesor, lo recomiendo.'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-18T00:00:00+00:00'::TIMESTAMPTZ, '99eec81f440336cb18444112f493c4de818baf2fae2260e4e9fbe54414d2879a'::TEXT, ARRAY[1045]::BIGINT[]),
    (332::BIGINT, 'Excelente profesor y persona, explica muy bien, se preocupa por dar bien el curso y hace la clase divertida. Resulta muy difícil dormirse en su clase. Nada más tenga cuidado con lo que dice, hace o simplemente como es porque le podría hacer bulling pero sus chistes y anécdotas son muy buenos :D'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-18T00:00:00+00:00'::TIMESTAMPTZ, 'a9b35e0e6c5e552d6346ff5b250dd5517df187cbbfef6f3ae30a0532fa51d769'::TEXT, ARRAY[1045]::BIGINT[]),
    (332::BIGINT, 'Buen profesor sabe explicar le gusta la materia y sabe explicar, proyectos grado dificil pero no imposible, recomendado no faltar debido ha como se da la clase. Lo recomiendo es calidad'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('10','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-18T00:00:00+00:00'::TIMESTAMPTZ, 'ba762c67fd6a62fc76fab0f7869a9a28976ef00b2a04b8b02e5aa275e476c062'::TEXT, ARRAY[1045]::BIGINT[]),
